fn get_min_val(a: &Vec<i8>) -> i8 {
    // Requires: a must not be empty
    // Ensures: returns the minimum value in the vector
    assert!(!a.is_empty(), "Vector must not be empty");
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    // Requires: a must not be empty
    // Ensures: returns the maximum value in the vector
    assert!(!a.is_empty(), "Vector must not be empty");
    *a.iter().max().unwrap()
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    // Requires: q must be between 0 and 100 inclusive
    // Ensures: returns the q-th quantile of the vector a
    assert!(q >= 0 && q <= 100, "Quantile percentage must be between 0 and 100");

    // Invariant: The vector a is not empty
    assert!(!a.is_empty(), "Vector must not be empty");

    if q == 0 {
        return get_min_val(&a);
    } else if q == 100 {
        return get_max_val(&a);
    }

    // Sort the vector
    let sorted = {
        let mut sorted = a.clone();
        sorted.sort();
        sorted
    };

    // Calculate the index for the quantile
    let index = (q as f64 / 100.0 * (sorted.len() as f64 - 1.0)).round() as usize;

    // Ensures: The index is within bounds of the sorted vector
    assert!(index < sorted.len(), "Index must be within bounds of the sorted vector");

    sorted[index]
}

fn main() {
    let data = vec![3, 1, 4, 1, 5, 9, 2, 6, 5];
    let quantile_0 = nanquantile(data.clone(), 0);
    let quantile_100 = nanquantile(data.clone(), 100);
    let quantile_50 = nanquantile(data.clone(), 50);

    println!("Min (0th quantile): {}", quantile_0);
    println!("Max (100th quantile): {}", quantile_100);
    println!("Median (50th quantile): {}", quantile_50);
}